CREATE TABLE IF NOT EXISTS coupons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,kind VARCHAR(10) NOT NULL,amount INT UNSIGNED NOT NULL,min_spend INT UNSIGNED NOT NULL DEFAULT 0,max_uses INT UNSIGNED NOT NULL,uses INT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_discounts (order_id BIGINT UNSIGNED PRIMARY KEY,coupon_id INT UNSIGNED NOT NULL,code VARCHAR(40) NOT NULL,amount INT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,display_name VARCHAR(60) NOT NULL,rating TINYINT UNSIGNED NOT NULL,body TEXT NOT NULL,photo VARCHAR(255) DEFAULT NULL,status VARCHAR(12) NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(order_id,product_id),INDEX(product_id,status,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS restock_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,size VARCHAR(10) NOT NULL,email VARCHAR(190) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'waiting',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(product_id,size,email),INDEX(status,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shipments (order_id BIGINT UNSIGNED PRIMARY KEY,consignment_id VARCHAR(100) NOT NULL,tracking_url VARCHAR(500) NOT NULL DEFAULT '',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
